def main():
    import sys
    import math

    def readints():
        return list(map(int, sys.stdin.readline().split()))

    n, p, q = readints()
    projects = [readints() for _ in range(n)]

    # Function to check if it's possible to achieve p experience and q money in d days
    def can_achieve(d):
        total_a = 0
        total_b = 0
        for a, b in projects:
            total_a += a * d
            total_b += b * d
        return total_a >= p and total_b >= q

    # Binary search for the minimum number of days
    low = 0
    high = max(max(p / a, q / b) for a, b in projects)
    while high - low > 1e-9:
        mid = (low + high) / 2
        if can_achieve(mid):
            high = mid
        else:
            low = mid

    print(f"{high:.12f}")

